                                  "/// Mini's ruleInstructions editor: one player-facing instruction per "
                                  'line.\n'
                                  '/// These are editor limits, not a claim that every legacy server value '
                                  'follows them.\n'
                                  'public struct MerchantTemplateRuleSteps: Equatable {\n'
                                  '    public static let maximumSteps = 12\n'
                                  '    public static let maximumStepLength = 60\n'
                                  '    private let sourceText: String?\n'
                                  '    public private(set) var rows: [String]\n'
                                  '    public private(set) var isEdited = false\n'
                                  '    public init(sourceText: String? = nil) {\n'
                                  '        self.sourceText = sourceText\n'
                                  '        let lines = (sourceText ?? "").components(separatedBy: "\\n")\n'
                                  '            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) '
                                  '}.filter { !$0.isEmpty }\n'
                                  '        rows = lines.isEmpty ? [""] : lines\n'
                                  '    }\n'
                                  '    /// Missing/null stays omitted; merely opening an old template never '
                                  'rewrites its text.\n'
                                  '    /// An explicit all-empty edit is an empty String, supported by the '
                                  'existing != null SQL.\n'
                                  '    public var wireValue: String? {\n'
                                  '        guard isEdited else { return sourceText }\n'
                                  '        return rows.map { $0.trimmingCharacters(in: '
                                  '.whitespacesAndNewlines) }\n'
                                  '            .filter { !$0.isEmpty }.joined(separator: "\\n")\n'
                                  '    }\n'
                                  '    public var isClearing: Bool {\n'
                                  '        isEdited && wireValue == "" && !(sourceText ?? '
                                  '"").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty\n'
                                  '    }\n'
                                  '    public var canAdd: Bool { rows.count < Self.maximumSteps }\n'
                                  '    public mutating func update(at index: Int, text: String) {\n'
                                  '        guard rows.indices.contains(index), rows[index] != text else { '
                                  'return }\n'
                                  '        rows[index] = text; isEdited = true\n'
                                  '    }\n'
                                  '    public mutating func add() {\n'
                                  '        guard canAdd else { return }\n'
                                  '        rows.append(""); isEdited = true\n'
                                  '    }\n'
                                  '    public mutating func remove(at index: Int) {\n'
                                  '        guard rows.count > 1, rows.indices.contains(index) else { return '
                                  '}\n'
                                  '        rows.remove(at: index); isEdited = true\n'
                                  '    }\n'
                                  '    public var blocker: String? {\n'
                                  '        guard isEdited else { return nil }\n'
                                  '        if rows.count > Self.maximumSteps { return '
                                  '"merchant.ruleSteps.countLimit" }\n'
                                  '        if rows.contains(where: { $0.rangeOfCharacter(from: .newlines) != '
                                  'nil }) { return "merchant.ruleSteps.oneLine" }\n'
                                  '        if rows.contains(where: { $0.utf16.count > Self.maximumStepLength '
                                  '}) { return "merchant.ruleSteps.textLimit" }\n'
                                  '        return nil\n'
                                  '    }\n'
                                  '}\n'
                                  '\n'
                                  '/// Existing Mini hint group. The enabled switch is editor state, never a '
                                  'backend flag.\n'
                                  'public struct MerchantTemplateHints: Equatable {\n'
                                  '    public enum Field: String, CaseIterable, Identifiable {\n'
                                  '        case hint1, hint2, answerReveal\n'
                                  '        public var id: String { rawValue }\n'
                                  '        public var titleKey: String { "merchant.hints." + rawValue }\n'
                                  '    }\n'
                                  '    private let sourceFields: [String: String]\n'
                                  '    private let sourceMethod: MerchantTemplateMethod?\n'
                                  '    private var values: [Field: String]\n'
                                  '    public private(set) var enabled: Bool\n'
                                  '    public private(set) var isEdited = false\n'
                                  '    public init(hint1: String? = nil, hint2: String? = nil, answerReveal: '
                                  'String? = nil,\n'
                                  '                method: MerchantTemplateMethod? = nil) {\n'
                                  '        sourceFields = ["hint1": hint1, "hint2": hint2, "answerReveal": '
                                  'answerReveal].compactMapValues { $0 }\n'
                                  '        // An absent/empty group has no method-dependent source state. '
                                  'Keep legacy\n'
                                  '        // no-hint templates equivalent to a freshly constructed empty '
                                  'group.\n'
                                  '        sourceMethod = sourceFields.values.contains { !$0.isEmpty } ? '
                                  'method : nil\n'
                                  '        values = [.hint1: hint1 ?? "", .hint2: hint2 ?? "", '
                                  '.answerReveal: answerReveal ?? ""]\n'
                                  '        enabled = sourceFields.values.contains { !$0.isEmpty }\n'
                                  '    }\n'
                                  '    public static func supports(_ method: MerchantTemplateMethod?) -> '
                                  'Bool {\n'
                                  '        method == .secretWord || method == .quiz || method == .gps\n'
                                  '    }\n'
                                  '    public func text(_ field: Field) -> String { values[field] ?? "" }\n'
                                  '    public mutating func update(_ field: Field, text: String) {\n'
                                  '        guard enabled, values[field] != text else { return }\n'
                                  '        values[field] = text; isEdited = true\n'
                                  '    }\n'
                                  '    public mutating func setEnabled(_ value: Bool) {\n'
                                  '        guard enabled != value else { return }\n'
                                  '        enabled = value; isEdited = true\n'
                                  '        if !value { for field in Field.allCases { values[field] = "" } }\n'
                                  '    }\n'
                                  '    /// The exact String fields support empty updates. Missing source '
                                  'values stay omitted\n'
                                  '    /// until this group is explicitly edited; no unrelated edit silently '
                                  'clears hints.\n'
                                  '    public var fields: [String: String] {\n'
                                  '        guard isEdited else { return sourceFields }\n'
                                  '        return Dictionary(uniqueKeysWithValues: Field.allCases.map { '
                                  '($0.rawValue, enabled ? text($0) : "") })\n'
                                  '    }\n'
                                  '    public var clearedFields: [Field] {\n'
                                  '        guard isEdited else { return [] }\n'
                                  '        return Field.allCases.filter { !(sourceFields[$0.rawValue] ?? '
                                  '"").isEmpty && fields[$0.rawValue] == "" }\n'
                                  '    }\n'
                                  '    public var previewStages: [Field] {\n'
                                  '        guard enabled else { return [] }\n'
                                  '        return Field.allCases.filter { !text($0).trimmingCharacters(in: '
                                  '.whitespacesAndNewlines).isEmpty }\n'
                                  '    }\n'
                                  '    public func blocker(method: MerchantTemplateMethod?) -> String? {\n'
                                  '        // Grandfather untouched legacy content. Changing to an '
                                  'unsupported completion\n'
                                  '        // method must not silently erase it as a hidden side effect.\n'
                                  '        enabled && !Self.supports(method) && (isEdited || method != '
                                  'sourceMethod)\n'
                                  '            ? "merchant.hints.methodConflict" : nil\n'
                                  '    }\n'
                                  '}\n'
                                  '\n'
                                  "/// The existing storyJson timeline, kept separate from the store's own "
                                  'story editor.\n'
                                  '/// Unknown source shapes remain opaque: no fallback may silently replace '
                                  'richer content.\n'
                                  'public struct MerchantTemplateStoryTimeline: Equatable {\n'
                                  '    public struct Beat: Equatable, Identifiable {\n'
                                  '        public let id: Int\n'
                                  '        public fileprivate(set) var text: String\n'
                                  '        public fileprivate(set) var tag: String\n'
                                  '        private let sourceImages: [String]?\n'
                                  '        private let legacyImage: String?\n'
                                  '        public var images: [String] { sourceImages ?? legacyImage.map { '
                                  '$0.isEmpty ? [] : [$0] } ?? [] }\n'
                                  '        public var imageReferenceCount: Int { (sourceImages?.count ?? 0) '
                                  '+ ((legacyImage ?? "").isEmpty ? 0 : 1) }\n'
                                  '        fileprivate init(id: Int, text: String = "", tag: String = "", '
                                  'images: [String]? = [], legacyImage: String? = nil) {\n'
                                  '            self.id = id; self.text = text; self.tag = tag; sourceImages '
                                  '= images; self.legacyImage = legacyImage\n'
                                  '        }\n'
                                  '        fileprivate var object: [String: Any] {\n'
                                  '            var result: [String: Any] = ["text": text, "tag": tag]\n'
                                  '            if let sourceImages { result["imgs"] = sourceImages }\n'
                                  '            if let legacyImage { result["img"] = legacyImage }\n'
                                  '            if sourceImages == nil && legacyImage == nil { result["imgs"] '
                                  '= [String]() }\n'
                                  '            return result\n'
                                  '        }\n'
                                  '        fileprivate var hasContent: Bool { !text.trimmingCharacters(in: '
                                  '.whitespacesAndNewlines).isEmpty || imageReferenceCount > 0 }\n'
                                  '    }\n'
                                  '    private let sourceText: String?\n'
                                  '    private let sourceJSON: String?\n'
                                  '    private let sourceImageCount: Int\n'
                                  '    private let sourceBeats: [Beat]\n'
                                  '    private var nextID: Int\n'
                                  '    public let isEditable: Bool\n'
                                  '    public private(set) var beats: [Beat]\n'
                                  '    public private(set) var enabled: Bool\n'
                                  '    public private(set) var isEdited = false\n'
                                  '    public init(storyText: String? = nil, storyJSON: String? = nil) {\n'
                                  '        sourceText = storyText; sourceJSON = storyJSON\n'
                                  '        if let raw = storyJSON, !raw.isEmpty {\n'
                                  '            if let parsed = Self.parse(raw) {\n'
                                  '                beats = parsed.isEmpty ? [Beat(id: 1, text: storyText ?? '
                                  '"")] : parsed\n'
                                  '                isEditable = true; enabled = !parsed.isEmpty || '
                                  '!(storyText ?? "").isEmpty\n'
                                  '            } else {\n'
                                  '                beats = []; isEditable = false; enabled = true\n'
                                  '            }\n'
                                  '        } else {\n'
                                  '            beats = [Beat(id: 1, text: storyText ?? "")]; isEditable = '
                                  'true\n'
                                  '            enabled = !(storyText ?? "").isEmpty\n'
                                  '        }\n'
                                  '        sourceBeats = beats\n'
                                  '        sourceImageCount = beats.reduce(0) { $0 + $1.imageReferenceCount '
                                  '}\n'
                                  '        nextID = beats.count + 1\n'
                                  '    }\n'
                                  '    private static func parse(_ raw: String) -> [Beat]? {\n'
                                  '        guard let array = try? JSONSerialization.jsonObject(with: '
                                  'Data(raw.utf8)) as? [[String: Any]] else { return nil }\n'
                                  '        var result: [Beat] = []\n'
                                  '        for (index, item) in array.enumerated() {\n'
                                  '            guard Set(item.keys).isSubset(of: ["text", "tag", "imgs", '
                                  '"img"]) else { return nil }\n'
                                  '            for key in ["text", "tag", "img"] {\n'
                                  '                if let value = item[key], !(value is NSNull), !(value is '
                                  'String) { return nil }\n'
                                  '            }\n'
                                  '            var images: [String]?\n'
                                  '            if let value = item["imgs"], !(value is NSNull) {\n'
                                  '                guard let strings = value as? [String] else { return nil '
                                  '}; images = strings\n'
                                  '            }\n'
                                  '            result.append(Beat(id: index + 1, text: (item["text"] as? '
                                  'String) ?? "", tag: (item["tag"] as? String) ?? "",\n'
                                  '                               images: images, legacyImage: item["img"] '
                                  'as? String))\n'
                                  '        }\n'
                                  '        return result\n'
                                  '    }\n'
                                  '    public mutating func setEnabled(_ value: Bool) {\n'
                                  '        guard isEditable, value != enabled else { return }\n'
                                  '        enabled = value; isEdited = true\n'
                                  '        if !value { beats = [Beat(id: nextID)]; nextID += 1 }\n'
                                  '    }\n'
                                  '    public mutating func update(_ id: Int, text: String? = nil, tag: '
                                  'String? = nil) {\n'
                                  '        guard isEditable, enabled, let index = beats.firstIndex(where: { '
                                  '$0.id == id }) else { return }\n'
                                  '        let before = beats[index]\n'
                                  '        if let text { beats[index].text = text }; if let tag { '
                                  'beats[index].tag = tag }\n'
                                  '        if beats[index] != before { isEdited = true }\n'
                                  '    }\n'
                                  '    public mutating func add() {\n'
                                  '        guard isEditable, enabled else { return }\n'
                                  '        beats.append(Beat(id: nextID)); nextID += 1; isEdited = true\n'
                                  '    }\n'
                                  '    public mutating func remove(_ id: Int) {\n'
                                  '        guard isEditable, enabled, beats.count > 1, let index = '
                                  'beats.firstIndex(where: { $0.id == id }) else { return }\n'
                                  '        beats.remove(at: index); isEdited = true\n'
                                  '    }\n'
                                  '    public mutating func move(_ id: Int, offset: Int) {\n'
                                  '        guard isEditable, enabled, [-1, 1].contains(offset), let index = '
                                  'beats.firstIndex(where: { $0.id == id }),\n'
                                  '              beats.indices.contains(index + offset) else { return }\n'
                                  '        beats.swapAt(index, index + offset); isEdited = true\n'
                                  '    }\n'
                                  '    public var previewBeats: [Beat] { enabled ? '
                                  'beats.filter(\\.hasContent) : [] }\n'
                                  '    private var fullProjection: String { previewBeats.map { '
                                  '$0.text.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { '
                                  '!$0.isEmpty }.joined(separator: "\\n") }\n'
                                  "    /// Mini's existing <=500 UTF-16-unit summary; full text remains in "
                                  'storyJson.\n'
                                  '    /// Keep a whole Swift Character at the boundary rather than '
                                  'splitting a surrogate.\n'
                                  '    public var textProjection: String {\n'
                                  '        var result = "", count = 0\n'
                                  '        for character in fullProjection {\n'
                                  '            let length = String(character).utf16.count\n'
                                  '            guard count + length <= 500 else { break }\n'
                                  '            result.append(character); count += length\n'
                                  '        }\n'
                                  '        return result\n'
                                  '    }\n'
                                  '    public var projectionIsShortened: Bool { isEdited && enabled && '
                                  'textProjection != fullProjection }\n'
                                  '    private var editedJSON: String? {\n'
                                  '        guard enabled, !previewBeats.isEmpty else { return "" }\n'
                                  '        guard let data = try? JSONSerialization.data(withJSONObject: '
                                  'previewBeats.map(\\.object), options: [.sortedKeys]) else { return nil }\n'
                                  '        return String(data: data, encoding: .utf8)\n'
                                  '    }\n'
                                  '    public var fields: [String: String] {\n'
                                  '        guard isEdited else { return ["storyText": sourceText, '
                                  '"storyJson": sourceJSON].compactMapValues { $0 } }\n'
                                  '        guard let json = editedJSON else { return [:] }\n'
                                  '        return ["storyText": enabled ? textProjection : "", "storyJson": '
                                  'json]\n'
                                  '    }\n'
                                  '    public var removedImageCount: Int { isEdited ? max(0, '
                                  'sourceImageCount - previewBeats.reduce(0) { $0 + $1.imageReferenceCount '
                                  '}) : 0 }\n'
                                  '    public var removedBeats: [Beat] {\n'
                                  '        guard isEdited else { return [] }\n'
                                  '        let retained = Set(previewBeats.map(\\.id))\n'
                                  '        return sourceBeats.filter { $0.hasContent && '
                                  '!retained.contains($0.id) }\n'
                                  '    }\n'
                                  '    public var clearsSource: Bool {\n'
                                  '        isEdited && fields["storyJson"] == "" && (!(sourceText ?? '
                                  '"").isEmpty || !(sourceJSON ?? "").isEmpty)\n'
                                  '    }\n'
                                  '    public var blocker: String? {\n'
                                  '        guard isEdited else { return nil }\n'
                                  '        guard isEditable else { return "merchant.storyTimeline.opaque" }\n'
                                  '        if enabled && beats.contains(where: { !$0.hasContent && '
                                  '!$0.tag.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }) {\n'
                                  '            return "merchant.storyTimeline.tagNeedsContent"\n'
                                  '        }\n'
                                  '        return editedJSON == nil ? '
                                  '"merchant.storyTimeline.encodingFailed" : nil\n'
                                  '    }\n'
                                  '}\n'
                                  '\n'
