                                  "        after, before = hunk['after'].encode(), hunk['before'].encode()\n"
                                  "        require(prefix.count(after) == 1, 'Missing/repeated club source "
                                  "interface span')\n"
                                  '        prefix = prefix.replace(after, before, 1)\n'
                                  '    slot = b"ADMISSION_FINGERPRINT = \'" + ADMISSION_FINGERPRINT.encode() '
                                  '+ b"\'"\n'
                                  "    require(prefix.count(slot) == 1, 'Unknown club admission fingerprint "
                                  "slot')\n"
