                                  '\n'
                                  'def validate_product_ui_budget(c, directory, root):\n'
                                  "    budget=c.get('product_ui_budget')\n"
                                  "    if budget!=_PRODUCT_UI_BUDGET or budget['measured'] is not False:\n"
                                  "        raise ValueError('Changed source-bound unmeasured product UI "
                                  "budget')\n"
                                  "    for path,expected in budget['source_sha256'].items():\n"
                                  '        if digest((Path(root)/path).read_bytes())!=expected:\n'
                                  "            raise ValueError('Product UI budget source changed: '+path)\n"
                                  '    totals={}\n'
                                  "    for identity,row in budget['methods'].items():\n"
                                  '        '
                                  "text=(Path(root)/row['source']).read_text();name=identity.split('.')[1]\n"
                                  "        match=re.search(r'(?m)^    func "
                                  "'+re.escape(name)+r'\\b[\\s\\S]*?^    }',text)\n"
                                  '        if match is None:\n'
                                  "            match=re.search(r'(?m)^    func "
                                  "'+re.escape(name)+r'\\b[^\\n]*}\\s*$',text)\n"
                                  '        if match is None or '
